macro_rules! destrify {
    () => {
        # [doc = " Convert a special reference type like \"&str\" into a reference to its owned"] # [doc = " type like \"&String\"."] fn destrify (ty : & mut Type) { if let Type :: Reference (ref mut tr) = ty { if let Some (lt) = & tr . lifetime { if lt . ident == "static" { return ; } } let path_ty : TypePath = parse2 (quote ! (Path)) . unwrap () ; let pathbuf_ty : Type = parse2 (quote ! (:: std :: path :: PathBuf)) . unwrap () ; let str_ty : TypePath = parse2 (quote ! (str)) . unwrap () ; let string_ty : Type = parse2 (quote ! (:: std :: string :: String)) . unwrap () ; let cstr_ty : TypePath = parse2 (quote ! (CStr)) . unwrap () ; let cstring_ty : Type = parse2 (quote ! (:: std :: ffi :: CString)) . unwrap () ; let osstr_ty : TypePath = parse2 (quote ! (OsStr)) . unwrap () ; let osstring_ty : Type = parse2 (quote ! (:: std :: ffi :: OsString)) . unwrap () ; match tr . elem . as_ref () { Type :: Path (ref path) if * path == cstr_ty => * tr . elem = cstring_ty , Type :: Path (ref path) if * path == osstr_ty => * tr . elem = osstring_ty , Type :: Path (ref path) if * path == path_ty => * tr . elem = pathbuf_ty , Type :: Path (ref path) if * path == str_ty => * tr . elem = string_ty , Type :: Slice (ts) => { let inner = (* ts . elem) . clone () ; let mut segments = Punctuated :: new () ; segments . push (format_ident ! ("std") . into ()) ; segments . push (format_ident ! ("vec") . into ()) ; let mut v : PathSegment = format_ident ! ("Vec") . into () ; let mut abga_args = Punctuated :: new () ; abga_args . push (GenericArgument :: Type (inner)) ; v . arguments = PathArguments :: AngleBracketed (AngleBracketedGenericArguments { colon2_token : None , lt_token : Token ! [<] (Span :: call_site ()) , args : abga_args , gt_token : Token ! [>] (Span :: call_site ()) , }) ; segments . push (v) ; * tr . elem = Type :: Path (TypePath { qself : None , path : Path { leading_colon : Some (Token ! [::] (Span :: call_site ())) , segments } }) ; } , _ => () , } ; } }
    };
}

destrify!();